import random
import itertools

def check_condition(m, colors):
    edges = list(itertools.combinations(range(m), 2))
    color_map = {edges[i]: colors[i] for i in range(len(edges))}
    triangles = list(itertools.combinations(range(m), 3))

    needed_sets = list(itertools.combinations(range(m), 3))
    found_sets = set()

    for u, v, w in triangles:
        e1 = tuple(sorted((u, v)))
        e2 = tuple(sorted((v, w)))
        e3 = tuple(sorted((w, u)))
        c_set = tuple(sorted([color_map[e1], color_map[e2], color_map[e3]]))
        if len(set(c_set)) == 3:
            found_sets.add(c_set)

    return len(found_sets) == len(needed_sets)

def random_search(m, iterations=100000):
    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)
    for _ in range(iterations):
        colors = [random.randint(0, m-1) for _ in range(num_edges)]
        if len(set(colors)) == m:
            if check_condition(m, colors):
                return True
    return False

for m in range(4, 8):
    print(f"m={m}: {random_search(m, 200000)}")

